            } else if (line.equals("values")) {
                System.out.println(tabela.values());
            }
        }
        sc.close();
    }
}

class TabelaHash {
    private ArrayList<Pair>[] table;

    @SuppressWarnings("unchecked")
    public TabelaHash(int M) {
        table = new ArrayList[M];
        for (int i = 0; i < M; i++) {
            table[i] = new ArrayList<>();
        }
    }

    private int hash(int key) {
        int M = table.length;
        int h = key % M;
        return h >= 0 ? h : h + M; // garantir índice não negativo
    }

    public void put(int key, String value) {
        int idx = hash(key);
        ArrayList<Pair> bucket = table[idx];
        for (int i = 0; i < bucket.size(); i++) {
            if (bucket.get(i).key == key) {
                bucket.get(i).value = value;
                return;
            }
        }
        bucket.add(new Pair(key, value));
    }

    public boolean remove(int key) {
        int idx = hash(key);
        ArrayList<Pair> bucket = table[idx];
        for (int i = bucket.size() - 1; i >= 0; i--) {
            if (bucket.get(i).key == key) {
                bucket.remove(i);
                return true;
            }
        }
        return false;
    }

    public String keys() {
        ArrayList<Integer> ks = new ArrayList<>();
        for (ArrayList<Pair> b : table) {
            for (Pair p : b) ks.add(p.key);
        }
        Collections.sort(ks);
        return ks.toString();
    }

    public String values() {
        ArrayList<String> vs = new ArrayList<>();
        for (ArrayList<Pair> b : table) {
            for (Pair p : b) vs.add(p.value);
        }
        Collections.sort(vs);
        return vs.toString();
    }

    public void print() {
        System.out.println(Arrays.toString(table));
    }
}

class Pair {
    int key;
    String value;

    Pair(int key, String value) {
        this.key = key;
        this.value = value;
    }

    public String toString() {
        return "<" + key + ", " + value + ">";
    }
