import java.util.*;

public class Solution {
    static class Node {
        int value;
        Node left, right;
        Node(int v) { value = v; }
    }

    static class BST {
        Node root;

        void add(int v) {
            root = add(root, v);
        }

        private Node add(Node n, int v) {
            if (n == null) return new Node(v);
            if (v < n.value) n.left = add(n.left, v);
            else if (v > n.value) n.right = add(n.right, v);
            return n;
        }

        void preOrder(List<Integer> out) {
            preOrder(root, out);
        }

        private void preOrder(Node n, List<Integer> out) {
            if (n == null) return;
            out.add(n.value);
            preOrder(n.left, out);
            preOrder(n.right, out);
        }

        int closestTo(int target) {
            if (root == null) throw new IllegalStateException("Árvore vazia");
            Node curr = root;
            int closest = root.value;
            while (curr != null) {
                if (Math.abs(curr.value - target) < Math.abs(closest - target)) {
                    closest = curr.value;
                }
                if (target < curr.value) {
                    curr = curr.left;
                } else if (target > curr.value) {
                    curr = curr.right;
                } else {
                    return target;
                }
            }
            return closest;
        }
    }

