class Pilha {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;
        int cap = sc.nextInt();
        int[] stack = new int[cap];
        int top = 0; // quantidade de elementos
        sc.nextLine(); // consome o fim de linha após o inteiro

        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.equals("end")) break;

            if (line.equals("pop")) {
                if (top == 0) {
                    System.out.println("empty");
                } else {
                    top--;
                }
            } else if (line.startsWith("push")) {
                String[] parts = line.split("\\s+");
                if (parts.length < 2) continue; // ignora entrada inválida
                if (top == cap) {
                    System.out.println("full");
                } else {
                    int val = Integer.parseInt(parts[1]);
                    stack[top++] = val;
                }
            } else if (line.equals("peek")) {
                if (top == 0) {
                    // Não especificado no enunciado, mas evita erro de execução
                    System.out.println("empty");
                } else {
                    System.out.println(stack[top - 1]);
                }
            } else if (line.equals("print")) {
                if (top == 0) {
                    System.out.println("empty");
                } else {
                    StringBuilder sb = new StringBuilder();
                    for (int i = 0; i < top; i++) {
                        if (i > 0) sb.append(' ');
                        sb.append(stack[i]);
                    }
                    System.out.println(sb.toString());
                }
            }
        }
        sc.close();
    }
}

