		if (node.isEmpty()) {
			node.setData(element);

			Node<T> emptyNodeRight = new Node();
			node.setRight(emptyNodeRight);

			Node<T> emptyNodeLeft = new Node();
			node.setLeft(emptyNodeLeft);
		} else {
