import java.util.*;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextLine()) return;
        String line = sc.nextLine().trim();
        if (line.isEmpty()) return;

        String[] tokens = line.split("\\s+");
        BST bst = new BST();
        for (String t : tokens) {
            bst.insert(Integer.parseInt(t));
        }
        bst.computeBalances(); // calcula alturas e balances em O(n)
        bst.printPreOrder();   // imprime no formato pedido
    }
}

class BST {
    static class Node {
        int key;
        Node left, right;
        int balance;
        Node(int k) { this.key = k; }
    }

    private Node root;

    public void insert(int key) {
        root = insert(root, key);
    }

    private Node insert(Node n, int key) {
        if (n == null) return new Node(key);
        if (key < n.key) n.left = insert(n.left, key);
        else if (key > n.key) n.right = insert(n.right, key);
        return n;
    }

    // Pós-ordem: retorna altura e define balance do nó
    public void computeBalances() {
        heightAndBalance(root);
    }

    private int heightAndBalance(Node n) {
        if (n == null) return -1;
        int hl = heightAndBalance(n.left);
        int hr = heightAndBalance(n.right);
        n.balance = hl - hr;
        return 1 + Math.max(hl, hr);
    }

    public void printPreOrder() {
        StringBuilder sb = new StringBuilder();
        preOrder(root, sb);
        if (sb.length() > 0) System.out.println(sb.toString().trim());
    }

    private void preOrder(Node n, StringBuilder sb) {
        if (n == null) return;
        sb.append(n.key).append(",").append(n.balance).append(" ");
        preOrder(n.left, sb);
        preOrder(n.right, sb);
    }
}

