            if (n == null) return;
            out.add(n.value);
            preOrder(n.left, out);
            preOrder(n.right, out);
        }

        int countLessThan(Node n, int x) {
            if (n == null) return 0;
            if (n.value < x) {
                // n e toda a esquerda são < x
                return 1 + countAll(n.left) + countLessThan(n.right, x);
            } else {
                // direita é >= n.value >= x, só pode haver menores à esquerda
                return countLessThan(n.left, x);
            }
        }

        int countAll(Node n) {
            if (n == null) return 0;
            return 1 + countAll(n.left) + countAll(n.right);
        }
    }

