public class MinhaSolucao {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextLine()) return;

        String line = sc.nextLine().trim();
        if (line.isEmpty()) {
            System.out.println("[]");
            return;
        }

        String[] parts = line.split("\\s+");
        int n = parts.length;
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) arr[i] = Integer.parseInt(parts[i]);

        int pivot = arr[0];
        int[] left = new int[n - 1];
        int[] right = new int[n - 1];
        int lc = 0, rc = 0;

        for (int i = 1; i < n; i++) {
            if (arr[i] <= pivot) left[lc++] = arr[i];
            else right[rc++] = arr[i];
        }

        int[] res = new int[n];
        int idx = 0;
        for (int i = 0; i < lc; i++) res[idx++] = left[i];
        res[idx++] = pivot;
        for (int i = 0; i < rc; i++) res[idx++] = right[i];

        System.out.println(Arrays.toString(res));
    }
}

